// === Inspired by 'NeonWordFountain' by 'Kazoops' ===
// Created as variant #5 by Uncler M
// Infused with creative algorithmic modifications.

// === Tab: mySketch ===
// パーティクルを管理する配列
let particles = [];
let characters; // 単語を保持する配列
let emitterAngle = 0; // パーティクル発生位置の角度
let neonPalette;

// 現在の単語インデックス
let currentWordIndex = 0;

function setup() {
  // キャンバスを作成
  createCanvas(windowWidth, windowHeight);
  background(10, 10, 15); // 背景を黒に設定

  // テキストを単語ごとに分割して配列に変換
  characters = "MERCURY AND THE WOODMAN　A Woodman was felling a tree on the bank of a river, when his axe glancing off the trunk flew out of his hands and fell into the water. As he stood by the water's edge lamenting his loss, Mercury appeared and asked him the reason for his grief and on learning what had happened, out of pity for his distress he dived into the river and bringing up a golden axe asked him if that was the one he had lost. The Woodman replied that it was not, and Mercury then dived a second time and bringing up a silver axe asked if that was his. No, that is not mine either, said the Woodman. Once more Mercury dived into the river, and brought up the missing axe. The Woodman was overjoyed at recovering his property, and thanked his benefactor warmly; and the latter was so pleased with his honesty that he made him a present of the other two axes. When the Woodman told the story to his companions, one of these was filled with envy of his good fortune and determined to try his luck for himself. So he went and began to fell a tree at the edge of the river, and presently contrived to let his axe drop into the water. Mercury appeared as before and on learning that his axe had fallen in he dived and brought up a golden axe as he had done on the previous occasion. Without waiting to be asked whether it was his or not the fellow cried, That's mine, that's mine, and stretched out his hand eagerly for the prize: but Mercury was so disgusted at his dishonesty that he not only declined to give him the golden axe, but also refused to recover for him the one he had let fall into the stream.   Honesty is the best policy."
    .split(" "); // スペースで単語を分割

  // ネオンカラーパレットを初期化
  neonPalette = [
    color(255, 0, 0),       // 赤
    color(255, 100, 0),    // オレンジ
    color(255, 200, 0),    // ゴールド
    color(0, 255, 0),      // 緑
    color(0, 255, 255),    // シアン
    color(0, 100, 255),    // 青
    color(200, 0, 255),    // 紫
    color(255, 0, 255)     // マゼンタ
  ];
}

function draw() {
  // === Variant 5: Symmetric Kaleidoscope Portal ===
  // Applying kaleidoscope coordinate distortion
  uM_rot = frameCount * 0.005;
  push();
  translate(width/2, height/2);
  rotate(uM_rot);
  scale(1.1);
  translate(-width/2, -height/2);

  // 背景を半透明で徐々に塗りつぶし
  background(0, 50);

  // 発生位置を円周上で計算
  let emitterX = width / 2 + cos(emitterAngle) * 150;
  let emitterY = height / 2 + sin(emitterAngle) * 150;
  emitterAngle += 0.04; // 発生位置をゆっくり回転させる

  // 新しいパーティクルを追加
  particles.push(new Particle(emitterX, emitterY));

  // 各パーティクルを描画し、更新
  for (let i = particles.length - 1; i >= 0; i--) {
    particles[i].update(); // パーティクルの位置を更新
    particles[i].show();   // パーティクルを描画

    // 消えるタイミングで配列から削除
    if (particles[i].isFinished()) {
      particles.splice(i, 1);
    }
  }

  pop();
}

// パーティクルクラス
class Particle {
  constructor(x, y) {
    this.pos = createVector(x, y); // 初期位置
    this.vel = p5.Vector.random2D().mult(random(1, 3)); // ランダムな速度
    this.lifespan = 255; // パーティクルの寿命
    this.char = characters[currentWordIndex]; // 現在の単語を取得
    this.size = random(20, 60); // パーティクルのサイズ
    this.rotation = random(TWO_PI); // 初期回転角
    this.rotationSpeed = random(-0.05, 0.05); // 回転速度

    // 次の単語インデックスに進む（ループ処理）
    currentWordIndex = (currentWordIndex + 1) % characters.length;
  }

  update() {
    this.pos.add(this.vel); // 位置を更新
    this.lifespan -= 2; // 寿命を減らす
    this.rotation += this.rotationSpeed; // 回転を更新
  }

  show() {
    push();
    translate(this.pos.x, this.pos.y);
    rotate(this.rotation); // 回転を適用

    // グロー効果を表現するためにブレンドモードを変更
    blendMode(ADD);

    // グロー層を描画
    for (let i = 10; i > 0; i--) {
      let alpha = map(i, 0, 10, 0, this.lifespan / 2); // 内側は濃く、外側は薄く
      let glowColor = color(random(neonPalette));
      glowColor.setAlpha(alpha / 40);
      noStroke();
      fill(glowColor);
      ellipse(0, 0, this.size + i * 8); // グロー部分を大きく描画
    }

    // 中心の文字
    let neonColor = random(neonPalette);
    neonColor.setAlpha(this.lifespan);
    fill(neonColor);
    textSize(this.size);
    textAlign(CENTER, CENTER);
    text(this.char, 0, 0);

    pop();
  }

  isFinished() {
    return this.lifespan < 0; // 寿命が尽きたらtrueを返す
  }
}

